// Lookup returns the tier of one operation. The second result is false when the
// service or operation is unknown to DevCloud — which is not the same as
// unimplemented, since an unknown service is not served at all.
func Lookup(service, op string) (Tier, bool) {
	svc, ok := Services[service]
	if !ok {
		return "", false
	}
	tier, ok := svc.Operations[op]
	return tier, ok
}

// Counts returns the number of operations per tier across every service.
func Counts() map[Tier]int {
	counts := make(map[Tier]int, 3)
	for _, svc := range Services {
		for _, tier := range svc.Operations {
			counts[tier]++
		}
	}
	return counts
}
